package com.praveen.product.controller;
import com.praveen.product.model.Product; import com.praveen.product.service.ProductService; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.util.List;
@RestController @RequestMapping("/api/products") public class ProductController { private final ProductService service; public ProductController(ProductService service){this.service=service;} @GetMapping public List<Product> all(){return service.all();} @GetMapping("/{id}") public Product get(@PathVariable Long id){return service.get(id);} @PostMapping public ResponseEntity<Product> create(@RequestBody Product p){return ResponseEntity.status(HttpStatus.CREATED).body(service.save(p));} @DeleteMapping("/{id}") @ResponseStatus(HttpStatus.NO_CONTENT) public void delete(@PathVariable Long id){service.delete(id);} }
